import{_ as e,o as l,c as i,a2 as s}from"./chunks/framework.CAUU6m5Y.js";const f=JSON.parse('{"title":"Architecture Decision Records (ADR Log)","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/decisions.md","filePath":"system-design/decisions.md"}'),n={name:"system-design/decisions.md"};function a(d,t,r,o,c,g){return l(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="architecture-decision-records-adr-log" tabindex="-1">Architecture Decision Records (ADR Log) <a class="header-anchor" href="#architecture-decision-records-adr-log" aria-label="Permalink to &quot;Architecture Decision Records (ADR Log)&quot;">​</a></h1><p>This log records every major design decision made in <code>18-flash-sale-inventory</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">ADR ID</th><th style="text-align:left;">Decision Made</th><th style="text-align:left;">Chosen Option</th><th style="text-align:left;">Alternatives Considered</th><th style="text-align:left;">Deciding Factors</th><th style="text-align:left;">Trade-Off Accepted</th><th style="text-align:left;">Revisit When</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>ADR-01</strong></td><td style="text-align:left;">High-Concurrency Stock Reservation</td><td style="text-align:left;"><strong>Atomic Conditional SQL (<code>WHERE available &gt;= :q</code>)</strong></td><td style="text-align:left;">Redis Lua, <code>SELECT FOR UPDATE</code>, Optimistic Locking</td><td style="text-align:left;">Direct ACID durability, database kernel-enforced check constraints.</td><td style="text-align:left;">Lower single-row throughput ceiling than pure in-memory Redis.</td><td style="text-align:left;">Single SKU traffic exceeds 20,000 writes/sec.</td></tr><tr><td style="text-align:left;"><strong>ADR-02</strong></td><td style="text-align:left;">Traffic Surge Leveling</td><td style="text-align:left;"><strong>Virtual Waiting Room (<code>flow/waiting_room.py</code>)</strong></td><td style="text-align:left;">Direct HTTP 429 Rate Limiting, Unbounded Queue</td><td style="text-align:left;">Preserves customer fairness and prevents payment gateway connection collapse.</td><td style="text-align:left;">Adds asynchronous polling round-trips for the client.</td><td style="text-align:left;">Traffic is distributed over hours rather than sudden drops.</td></tr><tr><td style="text-align:left;"><strong>ADR-03</strong></td><td style="text-align:left;">Currency Precision</td><td style="text-align:left;"><strong>Integer Minor Units (Cents)</strong></td><td style="text-align:left;">Floating-point numbers, Decimal objects</td><td style="text-align:left;">Eliminates IEEE 754 precision rounding errors and optimizes memory.</td><td style="text-align:left;">Requires frontend multiplication/division by 100 for display.</td><td style="text-align:left;">Multi-currency conversions with 4 decimal places are required.</td></tr><tr><td style="text-align:left;"><strong>ADR-04</strong></td><td style="text-align:left;">Distributed Lock Stale Write Defense</td><td style="text-align:left;"><strong>Monotonic Fencing Tokens (<code>transactions/distributed_lock.py</code>)</strong></td><td style="text-align:left;">Simple Redis lock, Redlock</td><td style="text-align:left;">Eliminates Martin Kleppmann stale-write hazards caused by GC pauses.</td><td style="text-align:left;">Storage layer must record highest observed fencing token.</td><td style="text-align:left;">All writes are handled by a single leader database.</td></tr><tr><td style="text-align:left;"><strong>ADR-05</strong></td><td style="text-align:left;">API Framework</td><td style="text-align:left;"><strong>FastAPI (Python 3.13)</strong></td><td style="text-align:left;">Express.js, Django, Go Gin</td><td style="text-align:left;">High-performance async ASGI loop, native Pydantic v2 validation, auto-generated OpenAPI docs.</td><td style="text-align:left;">Python global interpreter lock (mitigated by multi-process Uvicorn).</td><td style="text-align:left;">Microsecond-level network proxying is needed (migrate to Go/Rust).</td></tr><tr><td style="text-align:left;"><strong>ADR-06</strong></td><td style="text-align:left;">Observability Architecture</td><td style="text-align:left;"><strong>Prometheus Gauges + Invariant Auditor</strong></td><td style="text-align:left;">Passive log scanning, ELK stack alone</td><td style="text-align:left;">Continuous autonomous audit detects mathematical drift before customers notice.</td><td style="text-align:left;">Small background query overhead on database.</td><td style="text-align:left;">Database CPU exceeds 80% during peak flash sales.</td></tr></tbody></table>',3)])])}const u=e(n,[["render",a]]);export{f as __pageData,u as default};
